<section class="page-head"><span class="eyebrow">OPERATIONS</span><h1>Admin dashboard</h1><p>Live database counts. Revenue reporting will be enabled after payment integration.</p><a class="btn secondary" href="/admin/users">Manage users</a></section><div class="grid four stats"><article><span>Customers</span><strong><?= (int)$stats['customers'] ?></strong></article><article><span>Orders</span><strong><?= (int)$stats['orders'] ?></strong></article><article><span>Assessments</span><strong><?= (int)$stats['assessments'] ?></strong></article><article><span>Professional review flags</span><strong><?= (int)$stats['review'] ?></strong></article><article><span>Generated plans</span><strong><?= (int)$stats['plans'] ?></strong></article><article><span>Free-plan leads</span><strong><?= (int)$stats['leads'] ?></strong></article></div><section class="section"><h2>Recent assessments</h2><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Status</th><th>Screening</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach ($assessments as $a): ?><tr><td><?= Fitmeal\Core\Security::e($a['assessment_code']) ?></td><td><?= Fitmeal\Core\Security::e($a['name']) ?></td><td><?= Fitmeal\Core\Security::e($a['status']) ?></td><td><?= Fitmeal\Core\Security::e($a['screening_status']) ?></td><td><?= Fitmeal\Core\Security::e($a['submitted_at'] ?? '') ?></td><td><a href="/admin/assessments/<?= (int)$a['id'] ?>">View</a></td></tr><?php endforeach; ?></tbody></table></div></section><section class="section"><h2>Recent orders</h2><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Status</th><th>Amount</th><th>Date</th></tr></thead><tbody><?php foreach ($orders as $o): ?><tr><td><?= Fitmeal\Core\Security::e($o['order_number']) ?></td><td><?= Fitmeal\Core\Security::e($o['name']) ?></td><td><?= Fitmeal\Core\Security::e($o['status']) ?></td><td>₹<?= number_format(((int)$o['total_paise'])/100,2) ?></td><td><?= Fitmeal\Core\Security::e($o['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
